package com.ecotrack.backend.goal;
import com.ecotrack.backend.user.User; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="goals") public class Goal{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id") User user; String title; Double targetReductionPercent; Double targetEmission; Double baselineEmission; Double currentEmission=0.0; LocalDate startDate,endDate; String status="ACTIVE"; Instant createdAt=Instant.now(); public Long getId(){return id;} public User getUser(){return user;} public void setUser(User v){user=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public Double getTargetReductionPercent(){return targetReductionPercent;} public void setTargetReductionPercent(Double v){targetReductionPercent=v;} public Double getTargetEmission(){return targetEmission;} public void setTargetEmission(Double v){targetEmission=v;} public Double getBaselineEmission(){return baselineEmission;} public void setBaselineEmission(Double v){baselineEmission=v;} public Double getCurrentEmission(){return currentEmission;} public void setCurrentEmission(Double v){currentEmission=v;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate v){startDate=v;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate v){endDate=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
